/* Browser adapter for the documented OES and Nevco hockey profiles. */
const $=id=>document.getElementById(id),profile=document.body.dataset.profile;
const clock=new CanadianClocks[profile]();let sound=true,last=performance.now(),training;
const hornAudio=new RinkHorn(()=>{$('audio-note').textContent='Browser audio blocked. Check volume and site sound permission.';});
function fmt(t){t=Math.max(0,t);if(t>0&&t<60)return t.toFixed(1).padStart(4,'0');const n=Math.ceil(t);return String(Math.floor(n/60)).padStart(2,'0')+':'+String(n%60).padStart(2,'0');}
function log(text){const li=document.createElement('li');li.textContent=fmt(clock.time)+' · '+text;$('log').prepend(li);while($('log').children.length>30)$('log').lastChild.remove();}
function pulse(duration=.65){document.body.classList.add('honking');setTimeout(()=>document.body.classList.remove('honking'),duration*1000);if(sound)hornAudio.pulse(duration);else $('audio-note').textContent='Horn muted. Tap Sound off to enable audio.';}
function render(){
 const tod=new Intl.DateTimeFormat('en-CA',{timeZone:'America/Toronto',hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date());
 $('clock').textContent=clock.view==='time'?tod:clock.view==='break'?fmt(clock.breakTime):clock.view==='timeout'?fmt(clock.timeoutTime):fmt(clock.time);
 $('clock-label').textContent=clock.view==='time'?'TIME OF DAY':clock.view==='break'?'INTERMISSION':clock.view==='timeout'?'TIME OUT':'GAME TIME';$('period').textContent=clock.period;$('status').textContent=clock.running?'● CLOCK RUNNING':'● CLOCK STOPPED';
 for(const side of ['home','guest']){$(side).textContent=clock[side];$(side+'-name').textContent=clock.names?.[side]||(side==='guest'&&profile==='isc85x'?'VISITOR':side.toUpperCase());$(side+'-shots').textContent=clock.shots[side];$(side==='home'?'hp':'gp').textContent=clock.pen[side].slice(0,2).filter(Boolean).map(p=>p?'#'+p.player+' '+fmt(p.remaining):'—').join('\n')||'—  —:——';$(side+'-goal').hidden=!clock.goal[side];}
 $('penstate').textContent=clock.penRunning?(clock.holdQueue?'QUEUED PENALTIES HELD':'PENALTIES RUN'):'PENALTIES STOP';$('prompt').textContent=clock.message;
 const e=clock.edit;if(e?.type==='review'){const p=clock.pen[e.side][e.slot];$('entry').textContent=(e.side==='home'?'H':'G')+' '+(e.slot+1)+' '+fmt(p.remaining)+' #'+p.player;}else if(e?.type==='name')$('entry').textContent=e.chars.join('')+'▏';else if(e)$('entry').textContent=e.digits||'DEFAULT '+e.value;else $('entry').textContent=clock.view==='timeout'&&clock.timeoutTime===0?'TIMEOUT OVER +'+fmt(clock.timeoutElapsed):fmt(clock.time)+(clock.down===false?' UP':' DN')+' · P'+clock.period;
 $('screen-penalties').textContent=['home','guest'].map(side=>side.toUpperCase()+': '+clock.pen[side].map((p,i)=>p?'['+(i+1)+'] #'+p.player+' '+fmt(p.remaining)+(i>=2?' WAIT':''):'[empty]').join('  ')).join('\n');
 $('screen-shift').textContent=clock.shiftSet>0?'SHIFT '+fmt(clock.shiftTime):'';
 if($('remote-connect')){$('remote-connect').textContent=clock.remote?'Disconnect handheld':'Connect handheld';$('remote-switch').disabled=!clock.remote;$('remote-switch').textContent='Handheld '+(clock.running?'STOP':'RUN');}
 const rocker=document.querySelector('[data-key="rocker"]');if(rocker){rocker.setAttribute('aria-pressed',String(clock.running));}
 const memory=$('penalty-memory');memory.replaceChildren();for(const side of ['home','guest']){const p=document.createElement('p');p.textContent=side.toUpperCase()+': '+(clock.pen[side].map((pen,i)=>pen?'#'+pen.player+' '+fmt(pen.remaining)+(i>=2?' · queued':''):'empty').join(' / ')||'No penalties');memory.append(p);}
 const activeKeys=new Set();if(e){if(['player','penMinutes','penSeconds','review'].includes(e.type))activeKeys.add('penalty:'+e.side);else if(e.type==='score'||e.type==='addscore')activeKeys.add('score:'+e.side);else if(e.type==='shots'||e.type==='addshots')activeKeys.add('shots:'+e.side);else if(['minutes','seconds','fraction','main'].includes(e.type))activeKeys.add(profile==='nevco'?'time':'set');else if(e.type==='period')activeKeys.add('period');}
 document.querySelectorAll('[data-key]').forEach(b=>b.classList.toggle('entry-active',activeKeys.has(b.dataset.key)));
}
function key(k){clock.key(k);if(k==='horn'&&profile==='nevco4'&&!clock.set&&!clock.edit)pulse();training?.observe('key:'+k);for(const event of clock.events.splice(0))if(event==='horn'||event?.type==='horn')pulse(event.seconds||clock.hornSeconds||.65);if(!/^\d$/.test(k))log(clock.message);render();}
for(const b of document.querySelectorAll('[data-key]'))b.onclick=()=>key(b.dataset.key);
function setSound(value){sound=value;hornAudio.setMuted(!sound);$('sound').textContent='Sound '+(sound?'on':'off');$('sound').setAttribute('aria-pressed',String(sound));$('audio-note').textContent='';}
$('sound').onclick=()=>{setSound(!sound);if(sound)pulse();training.observe('ui:sound');};
$('length').onchange=()=>{log('Period preference applies on reset');training.observe('ui:length');};$('speed').onchange=()=>training.observe('ui:speed');
$('reset').onclick=()=>{if(confirm('Reset clock, scores and penalties?')){clock.periodLength=Number($('length').value);clock.reset();last=performance.now();render();log('New practice game');training.observe('ui:reset');}};
training=new RinkTutorials({profile,getState:()=>({model:clock,sound,speed:Number($('speed').value),length:Number($('length').value),setSound}),resetScenario:()=>{$('length').value='900';$('speed').value='1';clock.periodLength=900;clock.reset();setSound(true);last=performance.now();},onRender:render,log});
const hornButton=document.querySelector('[data-key="horn"]');let voice=null,hornLimit;
function releaseHorn(){clearTimeout(hornLimit);hornAudio.release(voice);voice=null;document.body.classList.remove('honking');}
function holdHorn(){if(['nevco4','nevco7'].includes(profile)&&clock.set){key('horn');return;}document.body.classList.add('honking');if(sound)voice=hornAudio.hold();else $('audio-note').textContent='Horn muted. Tap Sound off to enable audio.';training.observe('key:horn');if(profile==='nevco4'||profile==='nevco7')hornLimit=setTimeout(releaseHorn,4000);}
if(profile!=='harris'){hornButton.onclick=e=>{if(e.detail===0)key('horn');};hornButton.onpointerdown=e=>{hornButton.setPointerCapture(e.pointerId);holdHorn();};hornButton.onpointerup=releaseHorn;hornButton.onpointercancel=releaseHorn;hornButton.onkeydown=e=>{if(e.key===' '||e.key==='Enter'){e.preventDefault();if(!e.repeat)holdHorn();}};hornButton.onkeyup=releaseHorn;window.addEventListener('blur',releaseHorn);}
const savedButton=document.querySelector('[data-key="saved"]');if(savedButton){let timer,held=false;const begin=()=>{held=false;timer=setTimeout(()=>{held=true;key('saved');},700);};const end=()=>clearTimeout(timer);savedButton.onclick=()=>{if(!held){clock.message='HOLD SAVED TIME FOR ONE SECOND';render();}};savedButton.onpointerdown=e=>{savedButton.setPointerCapture(e.pointerId);begin();};savedButton.onpointerup=end;savedButton.onpointercancel=end;savedButton.onkeydown=e=>{if((e.key===' '||e.key==='Enter')&&!e.repeat){e.preventDefault();begin();}};savedButton.onkeyup=e=>{e.preventDefault();end();};}
document.addEventListener('keydown',e=>{if(['BUTTON','INPUT','SELECT','TEXTAREA'].includes(e.target.tagName))return;let k;if(e.code==='Space')k=profile==='harris'?'toggle':profile==='rotomatic'?'mainToggle':profile==='nevco4'?'rocker':clock.running?'hold':'run';else if(e.key==='Enter')k=['nevco4','nevco7'].includes(profile)?'yes':'enter';else if(e.key==='Escape')k=['nevco4','nevco7'].includes(profile)?'no':'cancel';else if(e.key.toLowerCase()==='h')k='horn';else if(/^\d$/.test(e.key)||[':', '/'].includes(e.key))k=e.key;if(k){e.preventDefault();key(k);}});
document.addEventListener('pointerdown',()=>{if(sound)hornAudio.unlock().catch(()=>{});},{once:true});
setInterval(()=>{const now=performance.now();clock.tick((now-last)/1000*Number($('speed').value));last=now;for(const event of clock.events.splice(0))if(event==='horn'||event?.type==='horn'){pulse(event.seconds||clock.hornSeconds||.65);log('Automatic horn');}render();training.observe('tick');},50);log('Practice console ready');render();

// Scoretec documents a five-second hold for these secondary functions.
if(profile==='scoretec')for(const [selector,heldKey,tapKey]of [['clear','resetHeld','clear'],['penToggle','penHeld','penToggle']]){const b=document.querySelector('[data-key="'+selector+'"]');let timer,held=false;const begin=()=>{held=false;timer=setTimeout(()=>{held=true;key(heldKey);},5000);};const end=()=>clearTimeout(timer);b.onclick=e=>{if(!held)key(tapKey);};b.onpointerdown=e=>{b.setPointerCapture(e.pointerId);begin();};b.onpointerup=end;b.onpointercancel=end;b.onkeydown=e=>{if([' ','Enter'].includes(e.key)&&!e.repeat){e.preventDefault();begin();}};b.onkeyup=e=>{if([' ','Enter'].includes(e.key)){e.preventDefault();end();if(!held)key(tapKey);}};window.addEventListener('blur',end);}
